pub trait Authenticator: Send + Sync {
    fn authenticate(&self, creds: &Credentials) -> Result<Principal, AuthError>;
}

pub struct Registry(HashMap<String, Box<dyn Authenticator>>);

impl Registry {
    pub fn login(&self, scheme: &str, creds: &Credentials) -> Result<Principal, AuthError> {
        self.0.get(scheme)
            .ok_or(AuthError::UnknownScheme)?
            .authenticate(creds)
    }
}
